from pathlib import Path
import json
import zipfile

ROOT=Path(__file__).resolve().parents[1]

def main():
    data=json.loads((ROOT/'assets/data/lab.json').read_text())
    metrics=data['metrics']['test']
    answer=('Object detection identifies objects and locates each one using a bounding box and class label. '
            'Image classification assigns a category to the whole image without locating individual objects. '
            'For example, classification might label a photograph "cat", while detection can identify two cats '
            'and one dog and draw a separate labeled box around each animal.')
    analysis=(f'The custom YOLO11 nano model was trained for 10 epochs on 42 training images, with 12 validation '
              f'images and 6 held-out test images. Test precision was {metrics["Precision"]*100:.2f}%, recall '
              f'{metrics["Recall"]*100:.2f}%, mAP50 {metrics["mAP50"]*100:.2f}%, and mAP50-95 '
              f'{metrics["mAP50-95"]*100:.2f}%. Training box loss decreased from 1.54 to 0.89; validation '
              f'mAP50 stayed near 80%. False detections, missed animals, and localization errors remain. '
              f'Six test images provide limited evidence of generalization.')
    answers=f'CSST106 Laboratory 6 YOLO Object Detection\n\nRESULTS AND ANALYSIS\n{analysis}\n\nWRITTEN QUESTION\nWhat is object detection in computer vision, and how does it differ from image classification? Explain using a real-world example.\n\n{answer}\n\nIMPLEMENTATION NOTE\nThe handout body uses YOLOv11 despite YOLOv8 in the filename. The completed run used 10 epochs as explicitly requested instead of the handout\'s 100-epoch example.\n'
    (ROOT/'downloads/lab6-answers.txt').write_text(answers,encoding='utf-8')
    table=''.join(f'<tr><td>{name}</td><td>{data["metrics"]["val"][name]*100:.2f}%</td><td>{metrics[name]*100:.2f}%</td></tr>' for name in ('Precision','Recall','mAP50','mAP50-95'))
    gallery=''.join(f'<figure><img src="{image["prediction"]}" alt="Saved test prediction for {image["id"]}"><figcaption>{image["id"]} · recorded Python prediction</figcaption></figure>' for image in data['images'] if image['split']=='test')
    html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lab 6 Report · YOLO Object Detection</title><link rel="icon" href="./assets/favicon.svg"><style>
*{{box-sizing:border-box}}body{{font:14px/1.75 'Segoe UI',Arial,sans-serif;color:#292c27;margin:0;background:#f8f7f2}}main{{max-width:900px;margin:35px auto;padding:55px;background:white;border:1px solid #e3e2d6}}h1{{font-size:35px;letter-spacing:-1.5px;line-height:1.2;margin:8px 0 20px}}h2{{font-size:21px;margin:30px 0 12px;color:#953e00}}p{{margin:10px 0;color:#535c49}}.eyebrow{{color:#934100;font-size:10px;letter-spacing:2px}}.controls{{display:flex;gap:15px;align-items:center;padding:18px;max-width:900px;margin:auto}}a,button{{color:#8c3c00}}button{{padding:10px 18px;border:1px solid #cdd1c3;border-radius:5px;background:white;cursor:pointer}}.details{{display:flex;gap:25px;flex-wrap:wrap;margin:25px 0}}label{{font-size:12px}}input{{border:0;border-bottom:1px solid #c6ccb8;padding:6px;max-width:200px}}table{{width:100%;border-collapse:collapse;margin:20px 0;font-size:13px}}td,th{{padding:10px 14px;border:1px solid #d9d9d9;text-align:left}}th{{background:#f3eee2}}tr:nth-child(even){{background:#fafaf5}}figure{{margin:0}}figure img{{display:block;width:100%;height:170px;object-fit:contain;background:#f4f3ec}}figcaption{{font-size:10px;margin:6px 0 14px;color:#6e7364}}.gallery{{display:grid;grid-template-columns:1fr 1fr;gap:15px}}.training{{width:100%;max-height:300px;object-fit:contain}}.note{{padding:15px;background:#fff4e5;border-left:3px solid #ff6b00;font-size:12px}}code{{font-family:Consolas,monospace;font-size:12px}}.sources{{font-size:11px}}@media(max-width:600px){{main{{padding:25px;margin:10px}}h1{{font-size:29px}}.gallery{{grid-template-columns:1fr}}}}@media print{{@page{{size:A4;margin:17mm}}body{{background:white;font-size:11px;line-height:1.65}}main{{border:0;margin:0;padding:0;max-width:none}}.controls{{display:none}}h1{{font-size:28px}}h2{{font-size:17px;break-after:avoid}}table,figure,.note{{break-inside:avoid}}figure img{{height:145px}}.training{{max-height:240px}}a{{color:inherit;text-decoration:none}}}}
</style></head><body><div class="controls"><a href="./index.html">← Back to the interactive laboratory</a><button onclick="window.print()">Print / Save as PDF</button></div><main><span class="eyebrow">CSST106 · COMPUTER VISION AND PERCEPTION</span><h1>Laboratory 6<br>YOLO Object Detection</h1><p>Pretrained inference, custom annotation, fine-tuning, and evaluation with YOLO11 nano.</p><div class="details"><label>Name <input aria-label="Student name"></label><label>Section <input aria-label="Section"></label><label>Date <input aria-label="Date"></label></div>
<p class="note">The document filename says YOLOv8; its activity body specifies YOLOv11. This report follows the body. This completed run used 10 epochs instead of the document's 100-epoch example.</p>
<h2>Objectives</h2><p>Gain hands-on object detection experience; prepare and annotate a custom dataset; train and fine-tune a YOLO model; and interpret training and evaluation metrics.</p>
<h2>Part 1 Real time pretrained detection</h2><p>The OpenCV webcam program loads <code>yolo11n.pt</code> and draws predicted classes, confidence scores, and boxes. The recorded detection speed was <strong>13.92 FPS</strong>, excluding capture/display and the first five warm-up frames. Browser inference speed depends on the visitor's device and is measured separately. Different lighting, distance, and object visibility can affect detections; no numerical webcam accuracy was measured.</p>
<h2>Part 2 Custom dataset preparation</h2><p>Sixty photographs (30 cats and 30 dogs) were manually annotated and split into 42 training, 12 validation, and 6 test images. Labels use <code>class_id x_center y_center width height</code> with normalized coordinates and classes 0 = cat and 1 = dog. Each image has a matching label file. The browser editor is an additional way to draw and export genuine labels.</p>
<h2>Part 3 Custom training</h2><p>The model was fine-tuned from pretrained YOLO11 nano weights using 640-pixel inputs, batch size 4, seed 42, and 10 epochs. The training script enforces a maximum of 10 epochs. The best checkpoint was selected using validation performance. Training box/class/DFL losses decreased, while validation mAP50 changed from about 80.67% to 80.47%.</p><figure><img class="training" src="./assets/results/results.png" alt="Actual saved ten-epoch training and validation plots"><figcaption>Original training plots from runs/detect/train-3.</figcaption></figure>
<h2>Part 4 Evaluation and inference</h2><p>The trained best checkpoint was evaluated on validation and test partitions and used on all six held-out test photographs. Values below are the genuine saved Ultralytics results, separate from live browser fixed-threshold precision/recall.</p><table><thead><tr><th>Metric</th><th>Validation · 12 images</th><th>Test · 6 images</th></tr></thead><tbody>{table}</tbody></table><p>{analysis}</p><div class="gallery">{gallery}</div>
<h2>Laboratory question and answer</h2><p><strong>What is object detection in computer vision, and how does it differ from image classification? Explain using a real-world example.</strong></p><p>{answer}</p>
<h2>Conclusion</h2><p>The activity demonstrates the complete path from a pretrained detector to a custom cat/dog experiment. Correct annotations, separate data partitions, saved checkpoint selection, and quantitative evaluation are essential. The difference between mAP50 and mAP50-95 shows that locating objects precisely remains a challenge.</p>
<h2>Sources and reproducibility</h2><p class="sources">Primary source: {data['sourceDocument']}. Original Python scripts are in the Python kit. Genuine history, images, and annotations are documented in SOURCE_MAP.md. Technical references: <a href="https://docs.ultralytics.com/models/yolo11/">Ultralytics YOLO11</a>, <a href="https://docs.ultralytics.com/modes/val/">validation documentation</a>, and <a href="https://onnxruntime.ai/docs/tutorials/web/">ONNX Runtime Web</a>.</p></main></body></html>'''
    (ROOT/'report.html').write_text(html,encoding='utf-8')
    with zipfile.ZipFile(ROOT/'downloads/lab6-python-kit.zip','w',zipfile.ZIP_DEFLATED) as archive:
        for path in (ROOT/'python').glob('part*.py'): archive.write(path,path.name)
        archive.write(ROOT/'python/requirements.txt','requirements.txt')
        archive.writestr('README.txt','Extract this kit and lab6-yolo-dataset.zip into the same new folder. Install requirements.txt. Run Part 1 for webcam detection; Parts 3 and 4 use the extracted data.yaml and dataset. Part 2 is for preparing your own new annotations in a fresh folder. Training defaults to 10 epochs and rejects more than 10. Scripts download pretrained weights when absent. A desktop display is required for OpenCV windows.\n')
    print('Generated printable report, written answers, and Python kit.')

if __name__=='__main__':main()
